using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["appName"] = "MyService",
        ["version"] = "1.0.0",
        ["maxRetries"] = 3,
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false,
        },
    };

    [McpServerResource(UriTemplate = "config://app", Name = "app_config",
        Title = "Application Configuration", MimeType = "application/json")]
    public static string GetAppConfig()
    {
        return JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/features", Name = "feature_flags",
        Title = "Feature Flags", MimeType = "application/json")]
    public static string GetFeatureFlags()
    {
        var features = (Dictionary<string, bool>)AppConfig["features"];
        return JsonSerializer.Serialize(features, new JsonSerializerOptions { WriteIndented = true });
    }
}
